/**
 * Quote encoding/signing tests, plus the golden-vector drift check.
 *
 * Golden vectors: `contracts/test-vectors/quotes.json` is generated by
 * `generateQuoteVectors()` in ./quote-vectors.test-helper.ts using fixed
 * TEST-ONLY keys. The last test asserts the committed file equals freshly
 * generated output, so it can't drift silently. To regenerate it after an
 * intentional change to the encoding or the fixtures, run:
 *
 *   UPDATE_QUOTE_VECTORS=1 node --import ./scripts/register-ts-resolver.mjs --test src/lib/bridge/quote.test.ts
 *
 * then commit the updated JSON. The Solidity/Soroban/Anchor contract tests
 * (Tasks 6–8) read that file to prove they verify what the server signs.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { privateKeyToAccount } from "viem/accounts";
import { StrKey } from "@stellar/stellar-sdk";
import {
  type BridgeQuote,
  ED25519_QUOTE_FIXED_LENGTH,
  EVM_QUOTE_TYPE_STRING,
  encodeQuoteBytes,
  ed25519PublicKeyFromSeed,
  hashEvmQuote,
  loadEd25519QuoteSignerSecret,
  loadEvmQuoteSignerKey,
  recoverEvmQuoteSigner,
  signEd25519Quote,
  signEvmQuote,
  verifyEd25519Quote,
} from "./quote";
import { buildForwarderHookData } from "../cctp/address-encoding";
import {
  QUOTE_VECTORS_PATH,
  TEST_ONLY_ED25519_SEED,
  TEST_ONLY_EVM_PRIVATE_KEY,
  generateQuoteVectors,
  serializeQuoteVectors,
} from "./quote-vectors.test-helper";

const EVM_KEY = TEST_ONLY_EVM_PRIVATE_KEY;
const EVM_ADDR = privateKeyToAccount(EVM_KEY).address;
const CHAIN_ID = 84532;
const VERIFIER = "0x000000000000000000000000000000000000bEEF" as const;

const evmQuote: BridgeQuote = {
  version: 1,
  sourceDomain: 6,
  destDomain: 27,
  user: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
  amount: BigInt(100_000_000),
  totalFee: BigInt(1_130_000),
  mintRecipient: `0x${"ab".repeat(32)}`,
  hookData: "0x1234",
  maxFee: BigInt(12_853),
  minFinality: 1000,
  deadline: 1_800_000_000,
  nonce: `0x${"cd".repeat(32)}`,
};

test("EVM type string is the agreed one", () => {
  assert.equal(
    EVM_QUOTE_TYPE_STRING,
    "Quote(uint8 version,uint32 sourceDomain,uint32 destDomain,address user,uint256 amount,uint256 totalFee,bytes32 mintRecipient,bytes hookData,uint256 maxFee,uint32 minFinality,uint64 deadline,bytes32 nonce)",
  );
});

test("EVM round trip recovers the signer", async () => {
  const sig = await signEvmQuote(evmQuote, CHAIN_ID, VERIFIER, EVM_KEY);
  const rec = await recoverEvmQuoteSigner(evmQuote, CHAIN_ID, VERIFIER, sig);
  assert.equal(rec, EVM_ADDR);
});

test("EVM: changing any single field changes the recovered address", async () => {
  const sig = await signEvmQuote(evmQuote, CHAIN_ID, VERIFIER, EVM_KEY);
  const mutations: Partial<BridgeQuote>[] = [
    { sourceDomain: 3 },
    { destDomain: 5 },
    { user: "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC" },
    { amount: BigInt(100_000_001) },
    { totalFee: BigInt(1_130_001) },
    { mintRecipient: `0x${"ab".repeat(31)}ac` },
    { hookData: "0x1235" },
    { hookData: "0x" },
    { maxFee: BigInt(12_854) },
    { minFinality: 2000 },
    { deadline: 1_800_000_001 },
    { nonce: `0x${"cd".repeat(31)}ce` },
  ];
  for (const m of mutations) {
    const rec = await recoverEvmQuoteSigner(
      { ...evmQuote, ...m },
      CHAIN_ID,
      VERIFIER,
      sig,
    );
    assert.notEqual(rec, EVM_ADDR, `mutation ${JSON.stringify(m, (_, v) => (typeof v === "bigint" ? v.toString() : v))}`);
  }
  // version, chainId, verifyingContract are bound too.
  assert.notEqual(
    await recoverEvmQuoteSigner({ ...evmQuote, version: 2 as 1 }, CHAIN_ID, VERIFIER, sig),
    EVM_ADDR,
  );
  assert.notEqual(await recoverEvmQuoteSigner(evmQuote, 8453, VERIFIER, sig), EVM_ADDR);
  assert.notEqual(
    await recoverEvmQuoteSigner(evmQuote, CHAIN_ID, "0x000000000000000000000000000000000000beee", sig),
    EVM_ADDR,
  );
});

test("EVM digest is 32 bytes and deterministic", () => {
  const d = hashEvmQuote(evmQuote, CHAIN_ID, VERIFIER);
  assert.match(d, /^0x[0-9a-f]{64}$/);
  assert.equal(d, hashEvmQuote({ ...evmQuote }, CHAIN_ID, VERIFIER));
});

// ---------- ed25519 ----------

const STELLAR_CONTRACT = StrKey.encodeContract(Buffer.alloc(32, 0x11));
const STELLAR_USER = StrKey.encodeEd25519PublicKey(Buffer.alloc(32, 0x33));

const stellarQuote: BridgeQuote = {
  ...evmQuote,
  sourceDomain: 27,
  destDomain: 6,
  user: STELLAR_USER,
  hookData: buildForwarderHookData(STELLAR_USER),
};

test("fixed length is 191 bytes", () => {
  assert.equal(ED25519_QUOTE_FIXED_LENGTH, 191);
});

test("ed25519 encoding length = fixed + hookData, layout spot checks", () => {
  const bytes = encodeQuoteBytes(stellarQuote, "stellar", STELLAR_CONTRACT);
  const hookLen = (stellarQuote.hookData.length - 2) / 2;
  assert.equal(bytes.length, ED25519_QUOTE_FIXED_LENGTH + hookLen);
  const b = Buffer.from(bytes);
  assert.equal(b.subarray(0, 15).toString("ascii"), "SETTU_BRIDGE_V1");
  assert.deepEqual(b.subarray(15, 47), Buffer.alloc(32, 0x11));
  assert.equal(b.readUInt32BE(47), 27);
  assert.equal(b.readUInt32BE(51), 6);
  assert.deepEqual(b.subarray(55, 87), Buffer.alloc(32, 0x33));
  assert.equal(b.readBigUInt64BE(87), BigInt(100_000_000));
  assert.equal(b.readBigUInt64BE(95), BigInt(1_130_000));
  assert.deepEqual(b.subarray(103, 135), Buffer.alloc(32, 0xab));
  assert.equal(b.readBigUInt64BE(135), BigInt(12_853));
  assert.equal(b.readUInt32BE(143), 1000);
  assert.equal(b.readBigUInt64BE(147), BigInt(1_800_000_000));
  assert.deepEqual(b.subarray(155, 187), Buffer.alloc(32, 0xcd));
  assert.equal(b.readUInt32BE(187), hookLen);
  assert.equal(`0x${b.subarray(191).toString("hex")}`, stellarQuote.hookData);
});

test("ed25519 encoding with empty hookData is exactly fixed length", () => {
  const bytes = encodeQuoteBytes({ ...stellarQuote, hookData: "0x" }, "stellar", STELLAR_CONTRACT);
  assert.equal(bytes.length, ED25519_QUOTE_FIXED_LENGTH);
});

test("ed25519 round trip verifies; flipping any byte fails", () => {
  const seed = TEST_ONLY_ED25519_SEED;
  const pub = ed25519PublicKeyFromSeed(seed);
  const bytes = encodeQuoteBytes(stellarQuote, "stellar", STELLAR_CONTRACT);
  const sig = signEd25519Quote(bytes, seed);
  assert.equal(sig.length, 64);
  assert.equal(verifyEd25519Quote(bytes, sig, pub), true);
  for (let i = 0; i < bytes.length; i++) {
    const t = new Uint8Array(bytes);
    t[i] ^= 0x01;
    assert.equal(verifyEd25519Quote(t, sig, pub), false, `byte ${i}`);
  }
  const badSig = new Uint8Array(sig);
  badSig[0] ^= 0x01;
  assert.equal(verifyEd25519Quote(bytes, badSig, pub), false);
});

test("RFC 8032 test vector 1 public key derivation", () => {
  // Sanity check that the raw-seed key construction is standard ed25519.
  assert.equal(
    Buffer.from(ed25519PublicKeyFromSeed(TEST_ONLY_ED25519_SEED)).toString("hex"),
    "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
  );
});

test("solana encoding uses raw pubkey bytes for user and program id", async () => {
  const { PublicKey } = await import("@solana/web3.js");
  const user = new PublicKey(Buffer.alloc(32, 0x44)).toBase58();
  const program = new PublicKey(Buffer.alloc(32, 0x22)).toBase58();
  const b = Buffer.from(
    encodeQuoteBytes({ ...stellarQuote, sourceDomain: 5, user, hookData: "0x" }, "solana", program),
  );
  assert.deepEqual(b.subarray(15, 47), Buffer.alloc(32, 0x22));
  assert.deepEqual(b.subarray(55, 87), Buffer.alloc(32, 0x44));
  assert.equal(b.readUInt32BE(47), 5);
});

test("encoding rejects bad inputs", () => {
  const enc = (q: Partial<BridgeQuote>, fam: "stellar" | "solana" = "stellar", cid = STELLAR_CONTRACT) =>
    () => encodeQuoteBytes({ ...stellarQuote, ...q }, fam, cid);
  assert.throws(enc({ mintRecipient: `0x${"ab".repeat(31)}` }));
  assert.throws(enc({ nonce: `0x${"cd".repeat(33)}` }));
  assert.throws(enc({ hookData: "0x123" as `0x${string}` }));
  assert.throws(enc({ amount: BigInt(2) ** BigInt(64) }));
  assert.throws(enc({ totalFee: BigInt(-1) }));
  assert.throws(enc({ maxFee: BigInt(2) ** BigInt(64) }));
  assert.throws(enc({ deadline: 1.5 }));
  assert.throws(enc({ sourceDomain: 2 ** 32 }));
  assert.throws(enc({ version: 2 as 1 }));
  assert.throws(enc({ user: "GBAD" }));
  assert.throws(enc({}, "stellar", "CBAD"));
  assert.throws(enc({}, "solana", STELLAR_CONTRACT));
  // u64 max itself is accepted.
  assert.doesNotThrow(enc({ amount: BigInt(2) ** BigInt(64) - BigInt(1) }));
});

// ---------- env key loaders ----------

function withEnv(name: string, value: string | undefined, fn: () => void) {
  const prev = process.env[name];
  if (value === undefined) delete process.env[name];
  else process.env[name] = value;
  try {
    fn();
  } finally {
    if (prev === undefined) delete process.env[name];
    else process.env[name] = prev;
  }
}

test("EVM signer key loader", () => {
  withEnv("BRIDGE_QUOTE_SIGNER_EVM_KEY", undefined, () =>
    assert.throws(loadEvmQuoteSignerKey, /BRIDGE_QUOTE_SIGNER_EVM_KEY/),
  );
  withEnv("BRIDGE_QUOTE_SIGNER_EVM_KEY", "0x1234", () =>
    assert.throws(loadEvmQuoteSignerKey, /BRIDGE_QUOTE_SIGNER_EVM_KEY/),
  );
  withEnv("BRIDGE_QUOTE_SIGNER_EVM_KEY", EVM_KEY.slice(2), () =>
    assert.equal(loadEvmQuoteSignerKey(), EVM_KEY),
  );
});

test("ed25519 signer secret loader accepts hex seed and S... secret", () => {
  const seed = TEST_ONLY_ED25519_SEED;
  withEnv("BRIDGE_QUOTE_SIGNER_ED25519_SECRET", undefined, () =>
    assert.throws(loadEd25519QuoteSignerSecret, /BRIDGE_QUOTE_SIGNER_ED25519_SECRET/),
  );
  withEnv("BRIDGE_QUOTE_SIGNER_ED25519_SECRET", "nope", () =>
    assert.throws(loadEd25519QuoteSignerSecret, /BRIDGE_QUOTE_SIGNER_ED25519_SECRET/),
  );
  withEnv("BRIDGE_QUOTE_SIGNER_ED25519_SECRET", Buffer.from(seed).toString("hex"), () =>
    assert.deepEqual(loadEd25519QuoteSignerSecret(), seed),
  );
  withEnv("BRIDGE_QUOTE_SIGNER_ED25519_SECRET", StrKey.encodeEd25519SecretSeed(Buffer.from(seed)), () =>
    assert.deepEqual(loadEd25519QuoteSignerSecret(), seed),
  );
});

// ---------- golden vectors ----------

test("golden vectors: generated cases self-verify", async () => {
  const v = await generateQuoteVectors();
  assert.deepEqual(v.cases.map((c) => c.name), ["evm", "stellar", "solana"]);
  const stellar = v.cases.find((c) => c.name === "stellar")!;
  assert.notEqual(stellar.quote.hookData, "0x");
});

test("golden vectors: committed file matches freshly generated output", async () => {
  const fresh = serializeQuoteVectors(await generateQuoteVectors());
  const file = path.resolve(QUOTE_VECTORS_PATH);
  if (process.env.UPDATE_QUOTE_VECTORS === "1") {
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, fresh);
  }
  const committed = readFileSync(file, "utf8");
  assert.equal(committed, fresh, "quotes.json drifted; see header of quote.test.ts to regenerate");
});
